WITH monthly AS (SELECT mktcode,tgtcode,DATE_TRUNC(bizdate,'MONTH') AS bucket,YEAR(DATE_TRUNC(bizdate,'MONTH'))*12+MONTH(DATE_TRUNC(bizdate,'MONTH')) AS ordinal,SUM(volume) AS metric FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate>=DATE_TRUNC(DATE_SUB('2026-04-14', INTERVAL '1' YEAR), 'YEAR') AND bizdate<='2026-04-14' GROUP BY mktcode,tgtcode,DATE_TRUNC(bizdate,'MONTH'),YEAR(DATE_TRUNC(bizdate,'MONTH'))*12+MONTH(DATE_TRUNC(bizdate,'MONTH'))), matched AS (SELECT mktcode,tgtcode,ordinal,ordinal-ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY ordinal) AS island FROM monthly WHERE metric>0), qualified AS (SELECT mktcode,tgtcode FROM matched GROUP BY mktcode,tgtcode,island HAVING COUNT(*)>=6) SELECT DISTINCT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14';
